/**
 * Coordinate lookup helper keyed strictly by ISO2 code or slug.
 * Zero country names are stored or looked up here.
 */
export function lookupCountryCoordinate(code?: string, slug?: string): CountryCoordinate | undefined {
  const cleanCode = (code || '').trim().toUpperCase();
  if (cleanCode && COUNTRY_COORDINATES[cleanCode]) {
    return COUNTRY_COORDINATES[cleanCode];
  }

  const cleanSlug = (slug || '').trim().toUpperCase();
  if (cleanSlug && COUNTRY_COORDINATES[cleanSlug]) {
    return COUNTRY_COORDINATES[cleanSlug];
  }

  return undefined;
}

/**
 * Analytical Natural Earth Projection
 * Converts longitude and latitude to Cartesian SVG canvas coordinates scaled for viewBox="60 45 880 380".
 */
export function projectCoordinates(lon: number, lat: number): [number, number] {
  const lambda = (lon * Math.PI) / 180;
  const phi = (lat * Math.PI) / 180;
  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const l = 0.8707 - 0.131979 * phi2 - 0.013791 * phi4 + 0.003971 * (phi4 * phi2) - 0.001529 * (phi4 * phi4);
  const dY = phi * (1.007226 + 0.015085 * phi2 - 0.044475 * phi4 + 0.028874 * (phi4 * phi2) - 0.005916 * (phi4 * phi4));
  const scale = 175;
  const x = 500 + scale * lambda * l;
  const y = 265 - scale * dY;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

/**
 * Exact Geographic Extent & Bounding Box for country geometry
 */

/**
 * Analytical Inverse of Natural Earth Projection
 * Converts Cartesian SVG canvas coordinates back to longitude and latitude [lon, lat].
 * Uses Newton-Raphson iteration on the polynomial latitude distortion function.
 */
export function unprojectCoordinates(x: number, y: number): [number, number] {
  const scale = 175;
  const targetDy = (265 - y) / scale;

  // Newton-Raphson to solve dY(phi) = targetDy
  let phi = targetDy;
  for (let i = 0; i < 6; i++) {
    const phi2 = phi * phi;
    const phi4 = phi2 * phi2;
    const f = phi * (1.007226 + 0.015085 * phi2 - 0.044475 * phi4 + 0.028874 * (phi4 * phi2) - 0.005916 * (phi4 * phi4)) - targetDy;
    const df = 1.007226 + 3 * 0.015085 * phi2 - 5 * 0.044475 * phi4 + 7 * 0.028874 * (phi4 * phi2) - 9 * 0.005916 * (phi4 * phi4);
    phi -= f / df;
  }

  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const l = 0.8707 - 0.131979 * phi2 - 0.013791 * phi4 + 0.003971 * (phi4 * phi2) - 0.001529 * (phi4 * phi4);
  const lambda = (x - 500) / (scale * l);

  const lat = Math.round(((phi * 180) / Math.PI) * 10000) / 10000;
  const lon = Math.round(((lambda * 180) / Math.PI) * 10000) / 10000;
  return [lon, lat];
}

/**
 * Calculates or retrieves the geographic bounding box [minLon, minLat, maxLon, maxLat]
 * for any country code. Used to query high-resolution satellite imagery matching the country.
 */
export function getCountryGeoBBox(countryCodeOrVector: string | CountryVector): [number, number, number, number] | null {
  const code = typeof countryCodeOrVector === 'string'
    ? countryCodeOrVector.trim().toUpperCase()
    : countryCodeOrVector.code.trim().toUpperCase();

  const ext = getCountryExtent(code);
  if (!ext) {
    const coord = COUNTRY_COORDINATES[code];
    if (coord) {
      return [coord.lng - 1.5, coord.lat - 1.0, coord.lng + 1.5, coord.lat + 1.0];
    }
    return null;
  }

  // Unproject top-left and bottom-right corners
  const [lon1, lat1] = unprojectCoordinates(ext.minX, ext.minY);
  const [lon2, lat2] = unprojectCoordinates(ext.maxX, ext.maxY);

  let minLon = Math.min(lon1, lon2);
  let maxLon = Math.max(lon1, lon2);
  let minLat = Math.min(lat1, lat2);
  let maxLat = Math.max(lat1, lat2);

  // 15% geographic padding for natural context around country borders
  const padLon = (maxLon - minLon) * 0.15;
  const padLat = (maxLat - minLat) * 0.15;

  minLon = Math.max(-180, Math.round((minLon - padLon) * 10) / 10);
  maxLon = Math.min(180, Math.round((maxLon + padLon) * 10) / 10);
  minLat = Math.max(-85, Math.round((minLat - padLat) * 10) / 10);
  maxLat = Math.min(85, Math.round((maxLat + padLat) * 10) / 10);

  return [minLon, minLat, maxLon, maxLat];
}

export interface GeographicExtent {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  width: number;
  height: number;
  cx: number;
  cy: number;
}

/**
 * Calculates the geographic bounding box and centroid from an SVG vector path.
 * Filters out antimeridian-wrapped fragments (such as Chukotka east of 180° mapped to the western edge)
 * so large transcontinental countries like Russia are bounded to their contiguous continental landmass.
 */
export function calculateCountryExtent(d: string): GeographicExtent | null {
  if (!d) return null;
  const subpaths = d.split(/(?=M)/);
  const boxes = subpaths.map(sp => {
    const nums = sp.match(/-?\d+(?:\.\d+)?/g)?.map(Number) || [];
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < nums.length; i += 2) {
      const x = nums[i], y = nums[i + 1];
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
    return { minX, minY, maxX, maxY, w: maxX - minX, h: maxY - minY, count: nums.length / 2 };
  }).filter(b => b.count >= 3);

  if (boxes.length === 0) return null;
  const largest = boxes.reduce((max, b) => b.count > max.count ? b : max, boxes[0]);
  const dominantCenterX = (largest.minX + largest.maxX) / 2;

  // Filter out subpaths wrapped across the antimeridian (e.g. Russia's Chukotka tip at X=124-153)
  const validBoxes = boxes.filter(b => {
    const cx = (b.minX + b.maxX) / 2;
    return Math.abs(cx - dominantCenterX) < 320;
  });

  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of validBoxes) {
    if (b.minX < minX) minX = b.minX;
    if (b.maxX > maxX) maxX = b.maxX;
    if (b.minY < minY) minY = b.minY;
    if (b.maxY > maxY) maxY = b.maxY;
  }

  const width = Math.round((maxX - minX) * 10) / 10;
  const height = Math.round((maxY - minY) * 10) / 10;
  const cx = Math.round(((minX + maxX) / 2) * 10) / 10;
  const cy = Math.round(((minY + maxY) / 2) * 10) / 10;

  return { minX, minY, maxX, maxY, width, height, cx, cy };
}

