const EXTENTS_CACHE = new Map<string, GeographicExtent | null>();

/**
 * Returns the cached or computed Geographic Extent for any country.
 * Uses precomputed extents for instant O(1) response, falling back to calculation.
 */
export function getCountryExtent(countryCodeOrVector: string | CountryVector): GeographicExtent | null {
  const code = typeof countryCodeOrVector === 'string'
    ? countryCodeOrVector.trim().toUpperCase()
    : countryCodeOrVector.code.trim().toUpperCase();

  if (PRECOMPUTED_COUNTRY_EXTENTS[code]) {
    return PRECOMPUTED_COUNTRY_EXTENTS[code];
  }

  if (EXTENTS_CACHE.has(code)) {
    return EXTENTS_CACHE.get(code)!;
  }

  const vec = typeof countryCodeOrVector === 'object'
    ? countryCodeOrVector
    : NATURAL_EARTH_COUNTRIES.find(c => c.code.toUpperCase() === code);

  if (!vec || !vec.d) {
    EXTENTS_CACHE.set(code, null);
    return null;
  }

  const ext = calculateCountryExtent(vec.d);
  EXTENTS_CACHE.set(code, ext);
  return ext;
}


/**
 * Normalization helper to associate an API country with its corresponding geographic vector.
 * Matches by ISO2 code, slug, or normalized name.
 */
export function findCountryVector(code?: string, slug?: string, name?: string): CountryVector | undefined {
  const cleanCode = (code || '').trim().toUpperCase();
  if (cleanCode) {
    const byCode = NATURAL_EARTH_COUNTRIES.find(c => c.code.toUpperCase() === cleanCode);
    if (byCode) return byCode;
  }

  const cleanSlug = (slug || '').trim().toLowerCase();
  if (cleanSlug) {
    const bySlug = NATURAL_EARTH_COUNTRIES.find(
      c => c.name.toLowerCase().replace(/\s+/g, '-') === cleanSlug ||
           c.code.toLowerCase() === cleanSlug
    );
    if (bySlug) return bySlug;
  }

  const cleanName = (name || '').trim().toLowerCase();
  if (cleanName) {
    const byName = NATURAL_EARTH_COUNTRIES.find(c => c.name.toLowerCase() === cleanName);
    if (byName) return byName;
  }

  return undefined;
}

